import{$,$$}from'./common.js';const stages={plan:{title:'A clear start.',copy:'Turn the possibilities into a practical plan.',tasks:[['Define the outcome','Alex',true],['Map the first version','Maya',false],['Choose the next step','Jordan',false]]},build:{title:'A little momentum.',copy:'Give the work a home and keep it moving.',tasks:[['Design the main flow','Maya',true],['Build the working version','Alex',true],['Review the details','Jordan',false]]},ship:{title:'Ready for the world.',copy:'Bring the last details together before launch.',tasks:[['Prepare release notes','Jordan',true],['Check the happy path','Alex',false],['Share the first version','Maya',false]]}};let current='plan';function update(){const stage=stages[current];$('#stageTitle').textContent=stage.title;$('#stageCopy').textContent=stage.copy;$('#taskList').replaceChildren();stage.tasks.forEach(([label,owner,checked],i)=>{const row=document.createElement('label');row.className='task';row.innerHTML=`<input type="checkbox" ${checked?'checked':''}><span>${label}</span><small>${owner}</small>`;row.querySelector('input').onchange=e=>{stage.tasks[i][2]=e.target.checked;progress()};$('#taskList').append(row)});progress()}function progress(){const n=Math.round(stages[current].tasks.filter(t=>t[2]).length/3*100);$('#readiness').textContent=n+'%';$('#progressBar').style.width=n+'%'}$$('[data-stage]').forEach(b=>b.onclick=()=>{current=b.dataset.stage;$$('[data-stage]').forEach(x=>x.classList.toggle('active',x===b));update()});$$('[data-billing]').forEach(b=>b.onclick=()=>{$$('[data-billing]').forEach(x=>x.classList.toggle('active',x===b));$('#studioPrice').textContent=b.dataset.billing==='annual'?'12':'15';$('#billingNote').textContent=b.dataset.billing==='annual'?'$144 per member per year in this pricing demo.':'Billed monthly in this pricing demo.'});const dialog=$('#signupDialog');$$('[data-signup]').forEach(b=>b.onclick=()=>{$('#signupResult').textContent='';dialog.showModal()});$('.dialog-close').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}};$('#signupForm').onsubmit=e=>{e.preventDefault();$('#signupResult').textContent='Demo complete. Your email was not saved or sent. Explore the sample workspace below.'};update();
